package ecdl

import (
	"errors"
	"math/bits"
	"math/rand"
)

// Curve is y^2 = x^3 + A x + B over F_P, with a group of prime order Order
// generated by G.
type Curve struct {
	P, A, B uint64
	Order   uint64
	G       Point
}

// Point is an affine point; Inf marks the identity O.
type Point struct {
	X, Y uint64
	Inf  bool
}

// Infinity is the group identity.
var Infinity = Point{Inf: true}

// FieldBits is b = ceil(log2 p), the width of one coordinate.
func (c *Curve) FieldBits() int { return bits.Len64(c.P - 1) }

func (c *Curve) rhs(x uint64) uint64 {
	p := c.P
	x3 := mulMod(mulMod(x, x, p), x, p)
	return addMod(addMod(x3, mulMod(c.A, x, p), p), c.B%p, p)
}

// OnCurve reports whether pt is O or a valid affine point.
func (c *Curve) OnCurve(pt Point) bool {
	if pt.Inf {
		return true
	}
	if pt.X >= c.P || pt.Y >= c.P {
		return false
	}
	return mulMod(pt.Y, pt.Y, c.P) == c.rhs(pt.X)
}

func (c *Curve) Neg(pt Point) Point {
	if pt.Inf || pt.Y == 0 {
		return pt
	}
	return Point{X: pt.X, Y: c.P - pt.Y}
}

// Add returns s + t using the affine chord-and-tangent law.
func (c *Curve) Add(s, t Point) Point {
	if s.Inf {
		return t
	}
	if t.Inf {
		return s
	}
	p := c.P
	var lambda uint64
	if s.X == t.X {
		if addMod(s.Y, t.Y, p) == 0 {
			return Infinity
		}
		num := addMod(mulMod(3, mulMod(s.X, s.X, p), p), c.A%p, p)
		lambda = mulMod(num, invMod(mulMod(2, s.Y, p), p), p)
	} else {
		lambda = mulMod(subMod(t.Y, s.Y, p), invMod(subMod(t.X, s.X, p), p), p)
	}
	x := subMod(subMod(mulMod(lambda, lambda, p), s.X, p), t.X, p)
	y := subMod(mulMod(lambda, subMod(s.X, x, p), p), s.Y, p)
	return Point{X: x, Y: y}
}

// Mul returns [k]pt.
func (c *Curve) Mul(k uint64, pt Point) Point {
	acc := Infinity
	for i := bits.Len64(k) - 1; i >= 0; i-- {
		acc = c.Add(acc, acc)
		if (k>>uint(i))&1 == 1 {
			acc = c.Add(acc, pt)
		}
	}
	return acc
}

// Points enumerates every affine point of the curve (toy sizes only).
func (c *Curve) Points() []Point {
	p := c.P
	roots := make(map[uint64]uint64, p/2+1)
	for y := uint64(0); y <= p/2; y++ {
		roots[mulMod(y, y, p)] = y
	}
	pts := make([]Point, 0, p+1)
	for x := uint64(0); x < p; x++ {
		y, ok := roots[c.rhs(x)]
		if !ok {
			continue
		}
		pts = append(pts, Point{X: x, Y: y})
		if y != 0 {
			pts = append(pts, Point{X: x, Y: p - y})
		}
	}
	return pts
}

// WindowPoints enumerates the affine points with x < xBound by taking the
// square root of x^3 + a x + b for each x. Its cost is about xBound field
// square-root tests, not the size of the group, so it is the cheap way to
// touch a compact coordinate window.
func (c *Curve) WindowPoints(xBound uint64) []Point {
	if xBound > c.P {
		xBound = c.P
	}
	pts := make([]Point, 0, 2*xBound)
	for x := uint64(0); x < xBound; x++ {
		y, ok := sqrtMod(c.rhs(x), c.P)
		if !ok {
			continue
		}
		if y != 0 && y > c.P-y {
			y = c.P - y
		}
		pts = append(pts, Point{X: x, Y: y})
		if y != 0 {
			pts = append(pts, Point{X: x, Y: c.P - y})
		}
	}
	return pts
}

// RandomPrimeOrderCurve searches for a curve over a random b-bit prime field
// whose group order is prime, by naive point counting. Toy sizes only.
func RandomPrimeOrderCurve(rng *rand.Rand, b int) (*Curve, error) {
	if b < 4 || b > 26 {
		return nil, errors.New("ecdl: field size must be between 4 and 26 bits for naive point counting")
	}
	lo := uint64(1) << uint(b-1)
	for tries := 0; tries < 100000; tries++ {
		p := lo + uint64(rng.Int63n(int64(lo)))
		if p <= 3 || !IsPrime(p) {
			continue
		}
		c := &Curve{P: p, A: uint64(rng.Int63n(int64(p))), B: uint64(rng.Int63n(int64(p)))}
		// 4a^3 + 27b^2 != 0 (mod p)
		disc := addMod(mulMod(4, powMod(c.A, 3, p), p), mulMod(27, mulMod(c.B, c.B, p), p), p)
		if disc == 0 {
			continue
		}
		pts := c.Points()
		n := uint64(len(pts)) + 1
		if !IsPrime(n) {
			continue
		}
		c.Order = n
		c.G = pts[rng.Intn(len(pts))]
		return c, nil
	}
	return nil, errors.New("ecdl: no prime-order curve found")
}
